function applyWomDoc(doc){if(!doc?.profiles)return false;state.profiles=doc.profiles||{};state.gains=doc.gains||{};state.snapshots=doc.snapshots||doc.history||{};state.achievements=doc.achievements||{};state.womFetchedAt=+(doc.fetchedAt||doc.savedAt||0);state.womSourceLatestAt=+(doc.sourceLatestAt||womLatestAt(state.profiles));return true}
async function loadWomSaved(){const doc=await window.UGV21.loadWom();return applyWomDoc(doc)?'saved baseline':'no saved WOM data'}
function validTemple(x){if(!x||typeof x!=='object'||x.error||x.errors)return false;const d=x.data??x;return !!(d&&typeof d==='object'&&d.items&&typeof d.items==='object')}
async function loadTempleSaved({discardBrowser=false}={}){if(!discardBrowser){state.temple=await window.UGV21.loadClog();state.templeShared=state.temple;return state.temple}let shared;try{shared=await window.UGSharedData.load('temple')}catch{shared=await staticJSON('data/temple-clog.json')}if(!shared?.players)throw new Error('No usable shared Collection Log');await window.UGTempleStore.clear(shared);state.templeShared=state.temple=shared;window.dispatchEvent(new CustomEvent('ug:data-updated',{detail:{key:TKEY,document:shared,source:'app'}}));return shared}
