function parseClogHunter(j,target){const root=j?.collectionLog||j?.collection_log||j;if(!root?.tabs)throw new Error('No Collection Log tabs found.');const items=[];function walk(n){if(Array.isArray(n)){n.forEach(walk);return}if(!n||typeof n!=='object')return;if(Number.isFinite(+(n.id??n.itemId))){items.push({id:+(n.id??n.itemId),name:n.name||n.itemName,count:+(n.count??n.quantity??(n.obtained?1:0))||0,date:n.date||null});return}Object.values(n).forEach(walk)}walk(root.tabs);if(items.length<20)throw new Error('Import looks incomplete.');const p=playerByKey(target);return{data:{player:p.name,player_name_with_capitalization:p.name,items,total_collections_in_response:items.length,total_collections_finished:items.filter(x=>x.count>0).length,total_collections_available:Math.max(items.length,collectionModel().known)}}}
function bindRecovery(){const input=$('#clogImport');if(input&&!input.dataset.bound){input.dataset.bound='1';input.onchange=async()=>{try{const file=input.files?.[0];if(!file)return;const j=JSON.parse(await file.text()),target=$('#clogImportTarget')?.value||'dikste';if(j?.players){const players=Object.fromEntries(Object.entries(j.players).filter(([key,value])=>playerByKey(key)&&validTemple(value)));if(!Object.keys(players).length)throw new Error('No valid group Collection Logs found.');state.temple={...j,players}}else if(validTemple(j)){state.temple={...(state.temple||{}),players:{...(state.temple?.players||{}),[target]:j},fetchedAt:Date.now()}}else{const p=parseClogHunter(j,target);state.temple={...(state.temple||{}),players:{...(state.temple?.players||{}),[target]:p},fetchedAt:Date.now()}}state.temple={...state.temple,_browserOverride:true};const stored=await persistTempleDoc(state.temple,{replace:true});setNotice('Browser-only Collection Log import applied. Shared GitHub data was not changed.'+(stored?'':' Browser storage failed; the import lasts only on this page.'),stored?'':'warn');renderMast();updateDataStatus();renderGim()}catch(e){setNotice('Import failed: '+esc(e.message||e),'warn')}finally{input.value=''}}}const ex=$('#clogExport');if(ex&&!ex.dataset.bound){ex.dataset.bound='1';ex.onclick=()=>{const blob=new Blob([JSON.stringify(state.temple,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`united-gimps-collection-log-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000)}}const reset=$('#clogReset');if(reset&&!reset.dataset.bound){reset.dataset.bound='1';reset.onclick=async()=>{await loadTempleSaved({discardBrowser:true});renderMast();updateDataStatus();renderGim();setNotice('Browser Collection Log override cleared; shared saved Temple snapshot restored.','')}}}
