function quality(diff){if(diff==null)return['approx','No datapoint'];if(diff<.6)return['exact','Same day'];if(diff<=7)return['near',`${Math.round(diff)} days away`];return['approx',`${Math.round(diff)} days away`]}
async function runTimeMachine(dateStr){const target=new Date(`${dateStr}T12:00:00`);if(Number.isNaN(+target))return;const go=$('#timeGo');if(go){go.disabled=true;go.textContent='Searching saved WOM history…'}setNotice('Using WOM snapshot history saved in this repository. No new WOM request is made by Time Machine.','warn');const res={};for(const p of PLAYERS){res[p.key]=cachedNearest(p,+target)||{snap:null,diffDays:null};await sleep(100)}state.timeTarget=target;state.timeResults=res;renderTimeResults(target,res);setNotice('');if(go){go.disabled=false;go.textContent='Enter the time machine'}}
