function renderGoals(){const h=$('#chronicleGoals');if(!h)return;const expanded=new Set([...h.querySelectorAll('details[open]')].map(d=>d.dataset.goalPlayer));const line=g=>`<div class="goal-line"><span>${esc(g.label)}</span><b>${fmt(g.left)} away</b><small>${esc(g.source)} · suggested goal</small></div>`;h.innerHTML=selectedPlayers().map(p=>{const goals=trackerGoals(p);return `<article class="goal-card ${p.core?'':'side'}" data-goal-player="${p.key}" style="--pc:${p.color}"><div class="goal-head"><img src="${p.portrait}" alt=""><h3>${p.name}</h3></div>${goals.slice(0,4).map(line).join('')}${goals.length>4?`<details data-goal-player="${p.key}"${expanded.has(p.key)?' open':''}><summary>Show ${goals.length-4} more goals</summary>${goals.slice(4).map(line).join('')}</details>`:''}${goals.length?'':'<div class="muted">Not enough data for suggested goals.</div>'}</article>`}).join('')}
function chronicleEventLink(e){if(e.type==='drop')return window.UGV21.itemLink(e.itemId,e.repeatDrop&&e.currentCount>1?`${e.name} · copy #${fmt(e.currentCount)}`:e.name);const data=snapData(e.key)||{},kind=e.metric in (data.skills||{})?(e.metric==='overall'&&/total level/i.test(e.name)?'level':'skill'):e.metric in (data.bosses||{})?'boss':e.metric in (data.activities||{})?'activity':e.metric in (data.computed||{})?'computed':null;return kind?window.UGV21.metricLink(kind,e.metric,e.name):esc(e.name)}
let chronoFilter='all',chronoPage=1,chronoPageSize=100;
function chroniclePageList(totalPages){
 const wanted=new Set();
 if(totalPages<=7){for(let i=1;i<=totalPages;i++)wanted.add(i)}
 else{
  wanted.add(1);wanted.add(totalPages);
  if(chronoPage<=3){wanted.add(2);wanted.add(3);wanted.add(4)}
  else if(chronoPage>=totalPages-2){wanted.add(totalPages-3);wanted.add(totalPages-2);wanted.add(totalPages-1)}
  else{wanted.add(chronoPage-1);wanted.add(chronoPage);wanted.add(chronoPage+1)}
 }
 const pages=[...wanted].filter(x=>x>=1&&x<=totalPages).sort((a,b)=>a-b),out=[];
 let previous=0;
 for(const page of pages){
  if(previous&&page>previous+1)out.push('<span class="chronicle-page-gap" aria-hidden="true">…</span>');
  out.push(`<button type="button" data-chrono-page="${page}" class="${page===chronoPage?'active':''}" ${page===chronoPage?'aria-current="page"':''}>${page}</button>`);
  previous=page;
 }
 return out.join('');
}
function chroniclePagerHtml(total,totalPages,start,end){
 if(!total)return'';
 const all=chronoPageSize==='all';
 const pages=all?'':`<div class="chronicle-page-list"><button type="button" class="chronicle-page-arrow" data-chrono-page="${Math.max(1,chronoPage-1)}" ${chronoPage<=1?'disabled':''} aria-label="Previous Chronicle page">‹</button>${chroniclePageList(totalPages)}<button type="button" class="chronicle-page-arrow" data-chrono-page="${Math.min(totalPages,chronoPage+1)}" ${chronoPage>=totalPages?'disabled':''} aria-label="Next Chronicle page">›</button></div>`;
 return `<div class="chronicle-pager-inner"><span class="chronicle-page-summary">${all?`${fmt(total)} events`:`${fmt(start+1)}–${fmt(end)} of ${fmt(total)}`}</span>${pages}<div class="chronicle-page-size" role="group" aria-label="Events per page"><span>Show</span><button type="button" data-chrono-size="100" class="${!all?'active':''}">100</button><button type="button" data-chrono-size="all" class="${all?'active':''}">All</button></div></div>`;
}
