 const end=recorded.length?Math.max(...recorded):Date.now(),first=all.flatMap(x=>x.eras.map(e=>+new Date(e.start)));
 const start=timelineRange==='max'?(first.length?Math.min(...first):end-864e5):end-Number(timelineRange)*864e5,span=Math.max(1,end-start);
 const data=all.map(({p,eras})=>({p,eras:eras.filter(e=>+new Date(e.end)>start&&+new Date(e.start)<=end).map((e,i)=>({...e,domId:'timeline-'+p.key.replace(/[^a-z]/g,'-')+'-'+i}))}));
 const rangeLabel=timelineRanges.find(([value])=>value===timelineRange)[1];$$('[data-period-status]').forEach(el=>el.textContent=rangeLabel);
 const colours={bossing:'#c47e52',skilling:'#73a775',combat:'#b66b65',mixed:'#aa91bd',unknown:'#8b887f',quiet:'#625b4c'};
